  <script>
    let audioCtx = null;
    function playTone(freq, duration, type = 'sine') {
      try {
        if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        if (audioCtx.state === 'suspended') audioCtx.resume();
        let osc = audioCtx.createOscillator();
        let gain = audioCtx.createGain();
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.frequency.value = freq;
        osc.type = type;
        gain.gain.setValueAtTime(0.08, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
        osc.start();
        osc.stop(audioCtx.currentTime + duration);
      } catch(e){}
    }

    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const scoreVal = document.getElementById('score');
    const highVal = document.getElementById('high');
    const overScreen = document.getElementById('over-screen');
    const startBtn = document.getElementById('start-btn');
    const welcomeTitle = document.getElementById('welcome-title');

    let snake = [];
    let food = {};
    let dx = 20;
    let dy = 0;
    let score = 0;
    let highScore = localStorage.getItem('snake_high') || 0;
    highVal.textContent = highScore;
    let gameInterval = null;
    const grid = 20;

    startBtn.onclick = () => {
      reset();
    };

    function reset() {
      snake = [
        {x: 160, y: 200},
        {x: 140, y: 200},
        {x: 120, y: 200}
      ];
      dx = 20;
      dy = 0;
      score = 0;
      scoreVal.textContent = score;
      overScreen.style.display = 'none';
      spawnFood();
      if(gameInterval) clearInterval(gameInterval);
      gameInterval = setInterval(gameLoop, 100);
      playTone(440, 0.1, 'sine');
    }

    function spawnFood() {
      let valid = false;
      while(!valid) {
        food.x = Math.floor(Math.random() * (canvas.width / grid)) * grid;
        food.y = Math.floor(Math.random() * (canvas.height / grid)) * grid;
        valid = true;
        for (let i = 0; i < snake.length; i++) {
          if (snake[i].x === food.x && snake[i].y === food.y) {
            valid = false;
            break;
          }
        }
      }
    }

    function gameLoop() {
      update();
      draw();
    }

    function update() {
      const head = {x: snake[0].x + dx, y: snake[0].y + dy};

      if (head.x < 0 || head.x >= canvas.width || head.y < 0 || head.y >= canvas.height) {
        gameOver();
        return;
      }

      for (let i = 0; i < snake.length; i++) {
        if (snake[i].x === head.x && snake[i].y === head.y) {
          gameOver();
          return;
        }
      }

      snake.unshift(head);

      if (head.x === food.x && head.y === food.y) {
        score += 10;
        scoreVal.textContent = score;
        if (score > highScore) {
          highScore = score;
          highVal.textContent = highScore;
          localStorage.setItem('snake_high', highScore);
        }
        playTone(600, 0.08, 'triangle');
        spawnFood();
      } else {
        snake.pop();
      }
    }

    function draw() {
      ctx.clearRect(0,0, canvas.width, canvas.height);

      ctx.strokeStyle = '#111827';
      ctx.lineWidth = 1;
      for(let x=0; x<canvas.width; x+=grid) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();
      }
      for(let y=0; y<canvas.height; y+=grid) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      snake.forEach((part, index) => {
        ctx.fillStyle = index === 0 ? '#38bdf8' : '#0284c7';
        ctx.shadowBlur = index === 0 ? 8 : 0;
        ctx.shadowColor = '#38bdf8';
        ctx.fillRect(part.x, part.y, grid-2, grid-2);
      });
      ctx.shadowBlur = 0;

      ctx.fillStyle = '#f43f5e';
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#f43f5e';
      ctx.fillRect(food.x, food.y, grid-2, grid-2);
      ctx.shadowBlur = 0;
    }

    function press(dir) {
      if (dir === 'UP' && dy === 0) { dx = 0; dy = -grid; playTone(300, 0.02, 'sine'); }
      if (dir === 'DOWN' && dy === 0) { dx = 0; dy = grid; playTone(300, 0.02, 'sine'); }
      if (dir === 'LEFT' && dx === 0) { dx = -grid; dy = 0; playTone(300, 0.02, 'sine'); }
      if (dir === 'RIGHT' && dx === 0) { dx = grid; dy = 0; playTone(300, 0.02, 'sine'); }
    }

    document.onkeydown = (e) => {
      if (e.key === 'ArrowUp') { press('UP'); e.preventDefault(); }
      if (e.key === 'ArrowDown') { press('DOWN'); e.preventDefault(); }
      if (e.key === 'ArrowLeft') { press('LEFT'); e.preventDefault(); }
      if (e.key === 'ArrowRight') { press('RIGHT'); e.preventDefault(); }
    };

    function gameOver() {
      clearInterval(gameInterval);
      playTone(180, 0.35, 'sawtooth');
      welcomeTitle.textContent = 'GAME OVER';
      startBtn.textContent = 'PLAY AGAIN';
      overScreen.style.display = 'flex';
    }
  </script>
</body>
</html>
